export const getElectronicsProducts = (): Product[] => ELECTRONICS_PRODUCTS;

export const getFeaturedElectronicsProducts = (): Product[] => 
  ELECTRONICS_PRODUCTS.filter(product => product.featured);

export const getElectronicsProductsByBadge = (badge: string): Product[] =>
  ELECTRONICS_PRODUCTS.filter(product => product.badge === badge);

export const getElectronicsProductsByPriceRange = (min: number, max: number): Product[] =>
  ELECTRONICS_PRODUCTS.filter(product => product.price >= min && product.price <= max);
